diff --git a/src/cart.js b/src/cart.js
index 9c7f263..65429b9 100644
--- a/src/cart.js
+++ b/src/cart.js
@@ -47,11 +47,19 @@ export class Cart {
    */
   total() {
     const subtotal = this.subtotal()
-    const taxed = Math.round(subtotal * (1 + TAX_RATE))
     const discount = this.discountCode ? DISCOUNT_CODES[this.discountCode] : null
-    if (!discount) return taxed
-    if (discount.type === 'percent') return Math.round(taxed * (1 - discount.value / 100))
-    return Math.max(0, taxed - discount.value)
+    // Apply discount to the subtotal first, then compute tax on the discounted amount.
+    let discountedSubtotal = subtotal
+    if (discount) {
+      if (discount.type === 'percent') {
+        discountedSubtotal = Math.round(subtotal * (1 - discount.value / 100))
+      } else if (discount.type === 'fixed') {
+        discountedSubtotal = subtotal - discount.value
+      }
+    }
+    // Compute tax on the discounted subtotal and clamp final total to >= 0
+    const taxed = Math.round(discountedSubtotal * (1 + TAX_RATE))
+    return Math.max(0, taxed)
   }

   /** Remove purchased quantities from the inventory and empty the cart. */
